using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class StairAGuideRecordSource {public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved Edit scene required");string repo=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));var plan=JObject.Parse(File.ReadAllText(repo+"/SourceAssets/T02_StairA/plan.json"));var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var blocks=new List<object>();int samples=0;foreach(var l in new[]{plan["legend"],plan["labLegend"],plan["coreLegend"]})for(int i=-3;i<=3;i++)for(int j=-4;j<=4;j++){var p=new Vector3((float)l["position"][0]+(float)l["width"]*i/6,-82,(float)l["position"][1]+(float)l["length"]*j/8);samples++;var hits=Physics.OverlapSphere(p+Vector3.up*.12f,.06f,~0,QueryTriggerInteraction.Ignore).Where(c=>c.transform.IsChildOf(root)&&!c.name.Contains("Floor")&&!c.name.Contains("Threshold")).ToArray();if(hits.Length>0)blocks.Add(new{point=new[]{p.x,p.z},hits=hits.Select(h=>h.name)});}if(blocks.Count>0)throw new Exception("Legend blocked: "+JsonConvert.SerializeObject(blocks));
 for(int i=1;i<=4;i++)AssetDatabase.ImportAsset("Assets/Afrer_Seconds/05.Model/Props/B5/Textures/SC_Display_"+i.ToString("00")+".png",ImportAssetOptions.ForceSynchronousImport);
 var data=new{title="B5 목적지 색 안내선 V0.01",author="송예찬",date="2026-11-08",source="SourceAssets/T02_StairA",plan,architecture=JObject.Parse(File.ReadAllText(repo+"/SourceAssets/T02_StairA/geometry.json")),models=JObject.Parse(File.ReadAllText(repo+"/SourceAssets/T02_StairA/model_manifest.json")),method="Local manufactured stair core/corridor meshes with bevels and shared PBR maps; destination floor paint; 8 upper luminaire lights; no new gameplay code",sourceRecord="Docs/검수/2026-11-08_T02_StairA/검수결과.md",legendSamples=samples,legendBlocked=blocks.Count,scope="C01/T01/C02/T02/VA; actual 16m stairs to B4 landing, B4 scene connection pending"};const string path="Assets/Afrer_Seconds/06.Data/AssetSources/T02_StairA_20261108.json";File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"..",path)),JsonConvert.SerializeObject(data,Formatting.Indented));AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));var result=new{asset=path,scene=s.path,dirty=s.isDirty,playing=Application.isPlaying,playerPosition=new[]{player.transform.position.x,player.transform.position.y,player.transform.position.z},runInBackground=PlayerSettings.runInBackground,legendSamples=samples,legendBlocked=blocks.Count};File.WriteAllText(repo+"/Docs/검수/2026-11-08_T02_StairA/final_state.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}}
